// Holds the record-fitted presets to the records they imitate: each one plays a keyboard phrase
// through the public CLAP interface at 44.1 kHz, is measured as song-corpus/scripts/features.py
// measures a separated stem (tests/stem_features.hpp), and must land inside the interquartile range
// of that stem on those records (tests/stem_reference.hpp, generated by tools/stem_gate_reference.py).
//
//   Scenario: a cassette keyboard preset sounds like the keyboards on the records
//     Given a preset named for a cheap home keyboard taped on a 4-track
//     When it plays the keyboard phrase
//     Then its centroid, rolloff, share above 3 kHz, stereo correlation and tape wobble
//          each lie inside the OTC `other` stem's interquartile range
//
//   Scenario: the gate tells a clean keyboard from a taped one
//     Given the Porta FM toy organ, which has no tape stage
//     When it plays the same phrase
//     Then its tape wobble and stereo correlation fall outside that range
//
//   stem_gate_tests <YANES.clap>

#include "clap_harness.hpp"
#include "stem_features.hpp"
#include "stem_reference.hpp"
#include "../src/params.hpp"

#include <cmath>
#include <cstdio>
#include <cstring>
#include <iterator>
#include <tuple>
#include <vector>

using namespace harness;
namespace P = yanes::params;

namespace {

struct Note { int key; double start, length; };

// A melody of quarter notes and held half notes at 100 bpm, C4 to D5, legato but not tied.
std::vector<Note> phrase() {
  constexpr int keys[] = {60, 64, 67, 72, 71, 67, 64, 65, 62, 65, 69, 74, 72, 67, 64, 60, 62, 64, 65, 67, 69, 67, 65, 64};
  constexpr double beats[] = {1, 1, 1, 2, 1, 1, 1, 2, 1, 1, 1, 2, 1, 1, 1, 2, 0.67, 0.67, 0.67, 1.33, 1, 1, 1, 2};
  std::vector<Note> notes;
  double t = 0.2;
  for (size_t i = 0; i < std::size(keys); ++i) {
    const double length = 0.6 * beats[i];
    notes.push_back({keys[i], t, 0.92 * length});
    t += length;
  }
  return notes;
}

int preset_id(const char* name) {
  for (size_t i = 0; i < std::size(P::kPresetNames); ++i)
    if (std::strcmp(P::kPresetNames[i], name) == 0) return static_cast<int>(i);
  return -1;
}

struct Render { std::vector<float> left, right; };

Render play(const char* clap, int preset) {
  constexpr uint32_t block = 256;
  Library library(clap);
  const clap_plugin_t* plugin = library.create();
  set_param(plugin, P::kPreset, preset);
  const auto notes = phrase();
  const double seconds = notes.back().start + notes.back().length / 0.92 + 0.6;
  Render out;
  {
    Runner runner(plugin, stem::kRate, block);
    const size_t frames = static_cast<size_t>(seconds * stem::kRate);
    for (size_t at = 0; at < frames; at += block) {
      Events events;
      for (const Note& n : notes) {
        const size_t on = static_cast<size_t>(n.start * stem::kRate), off = static_cast<size_t>((n.start + n.length) * stem::kRate);
        for (const auto& [when, type, velocity] : {std::tuple{on, CLAP_EVENT_NOTE_ON, 0.8}, std::tuple{off, CLAP_EVENT_NOTE_OFF, 0.0}}) {
          if (when < at || when >= at + block) continue;
          auto e = note_event(static_cast<uint16_t>(type), 0, static_cast<int16_t>(n.key), -1, velocity);
          e.header.time = static_cast<uint32_t>(when - at);
          events.push(e);
        }
      }
      runner.run(&events);
      out.left.insert(out.left.end(), runner.left().begin(), runner.left().end());
      out.right.insert(out.right.end(), runner.right().begin(), runner.right().end());
    }
  }
  plugin->destroy(plugin);
  return out;
}

const stem::Reference* reference(const char* group, const char* stem_name) {
  for (const auto& r : stem::kReferences)
    if (std::strcmp(r.group, group) == 0 && std::strcmp(r.stem, stem_name) == 0) return &r;
  return nullptr;
}

struct Check { const char* name; const char* unit; double measured; stem::Range range; };

std::vector<Check> checks(const stem::Features& f, const stem::Reference& r) {
  return {{"centroid", "Hz", f.centroid_hz, r.centroid_hz},
          {"rolloff 85%", "Hz", f.rolloff85_hz, r.rolloff85_hz},
          {"share above 3 kHz", "dB", f.hf_share_db, r.hf_share_db},
          {"L/R correlation", "", f.corr, r.corr},
          {"tape wobble", "cents", f.wobble_cents, r.wobble_cents}};
}

bool inside(const Check& c) { return std::isfinite(c.measured) && c.measured >= c.range.q25 && c.measured <= c.range.q75; }

}  // namespace

int main(int argc, char** argv) {
  if (argc != 2) {
    std::fprintf(stderr, "usage: %s YANES.clap\n", argv[0]);
    return 2;
  }
  struct Case { const char* preset; const char* group; const char* stem; };
  constexpr Case cases[] = {
      {"4-track toy organ", "OTC", "other"},
      {"4-track melody keyboard", "OTC", "other"},
  };
  int failures = 0;
  for (const Case& c : cases) {
    const int id = preset_id(c.preset);
    const stem::Reference* r = reference(c.group, c.stem);
    std::printf("%s against %s %s (%d records)\n", c.preset, c.group, c.stem, r ? r->tracks : 0);
    if (id < 0 || !r) {
      std::printf("  FAIL  no such preset or reference\n");
      ++failures;
      continue;
    }
    const Render take = play(argv[1], id);
    for (const Check& k : checks(stem::measure(take.left, take.right), *r)) {
      const bool ok = inside(k);
      failures += !ok;
      std::printf("  %s  %-18s %8.3f %-5s  [%.3f, %.3f]\n", ok ? "pass" : "FAIL", k.name, k.measured, k.unit, k.range.q25, k.range.q75);
    }
  }
  const stem::Reference* otc = reference("OTC", "other");
  const Render control = play(argv[1], preset_id("Porta FM toy organ"));
  const auto control_checks = checks(stem::measure(control.left, control.right), *otc);
  std::printf("Control: Porta FM toy organ, no tape stage\n");
  for (const Check& k : control_checks)
    std::printf("  %-6s %-18s %8.3f %-5s  [%.3f, %.3f]\n", inside(k) ? "inside" : "out", k.name, k.measured, k.unit, k.range.q25, k.range.q75);
  if (inside(control_checks[3]) || inside(control_checks[4])) {
    std::printf("  FAIL  the gate passes a keyboard with no tape wobble and a mono image\n");
    ++failures;
  }
  std::printf("%s\n", failures ? "FAILED" : "PASSED");
  return failures ? 1 : 0;
}
